// Jours ouvrables (lu-ve) hors jours fériés genevois et fermetures (AC_JOURS_FERMES = "2027-07-19,2027-07-20").
function paques(a) {
  const b = Math.floor(a / 100), c = a % 100, d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25),
    g = Math.floor((b - f + 1) / 3), h = (19 * (a % 19) + b - d - g + 15) % 30, i = Math.floor(c / 4), k = c % 4,
    l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor(((a % 19) + 11 * h + 22 * l) / 451);
  return DateTime.fromObject({ year: a, month: Math.floor((h + l - 7 * m + 114) / 31), day: ((h + l - 7 * m + 114) % 31) + 1 }, { zone: 'Europe/Zurich' });
}
function feries(a) {
  const p = paques(a), j = (n) => p.plus({ days: n }).toISODate();
  const jeune = DateTime.fromObject({ year: a, month: 9, day: 1 }, { zone: 'Europe/Zurich' });
  const premierDimanche = jeune.plus({ days: (7 - jeune.weekday) % 7 });
  return [a + '-01-01', j(-2), j(1), j(39), j(50), a + '-08-01', premierDimanche.plus({ days: 4 }).toISODate(), a + '-12-25', a + '-12-31']
    .concat(String($env.AC_JOURS_FERMES || '').split(',').map((s) => s.trim()).filter(Boolean));
}
const estOuvrable = (dt) => dt.weekday <= 5 && !feries(dt.year).includes(dt.toISODate());
const maintenant = () => DateTime.now().setZone('Europe/Zurich');

const t = maintenant();
let premier = t.startOf('month');
while (!estOuvrable(premier)) premier = premier.plus({ days: 1 });
const debut = t.minus({ months: 1 }).startOf('month'), fin = t.startOf('month');
return [{ json: { ok: premier.toISODate() === t.toISODate(), debut: debut.toISO(), fin: fin.toISO(), debutMs: debut.toMillis(), finMs: fin.toMillis(), mois: debut.setLocale('fr-CH').toFormat('MMMM yyyy') } }];

// Correspondance des champs personnalisés Pipedrive (clés de 40 caractères) et des identifiants,
// lus dans l'environnement : AC_PD_CHAMPS et AC_PD_IDS (voir automation/n8n/parametres.env.example).
