const IDS = JSON.parse($env.AC_PD_IDS || '{}');
const champ = (objet, nom) => (C[nom] && objet ? objet[C[nom]] : undefined);
function champs(valeurs) { const o = {}; for (const [k, v] of Object.entries(valeurs)) if (C[k] && v !== undefined) o[C[k]] = v; return o; }
// Service en toutes lettres, avec son article : « vos travaux de peinture ».
const SERVICES = { placo: 'vos travaux de placo', peinture: 'vos travaux de peinture', 'isolation-acoustique': 'votre isolation acoustique',
  'cloisons-isothermes': 'vos cloisons isolantes', plusieurs: 'vos travaux', 'ne-sait-pas': 'vos travaux' };
const serviceTexte = (slug) => SERVICES[slug] || 'vos travaux';
const majuscule = (s) => s.charAt(0).toUpperCase() + s.slice(1);
