const p = $('Premier jour ouvrable ?').first().json;
const affaires = $('Affaires (Pipedrive)').first().json.data || [];
const dans = (d) => d && Date.parse(String(d).replace(' ', 'T') + 'Z') >= p.debutMs && Date.parse(String(d).replace(' ', 'T') + 'Z') < p.finMs;
const mois = affaires.filter((a) => dans(a.add_time));
const parPrio = (x) => mois.filter((a) => champ(a, 'priorite') === x).length;
const offres = affaires.filter((a) => dans(champ(a, 'date_offre') + ' 12:00:00')).length;
const gagnees = affaires.filter((a) => a.status === 'won' && dans(a.won_time));
