const delais = mois.filter((a) => champ(a, 'date_premier_contact')).map((a) => (Date.parse(champ(a, 'date_premier_contact')) - Date.parse(a.add_time.replace(' ', 'T') + 'Z')) / 3600000).sort((x, y) => x - y);
const mediane = delais.length ? delais[Math.floor(delais.length / 2)].toFixed(1) + ' h' : 'n.d.';
const sources = {};
for (const a of mois) { const s = champ(a, 'source') || 'inconnue'; sources[s] = (sources[s] || 0) + 1; }
const umami = $('Umami : statistiques').first().json || {};
const ev = $('Umami : événements').first().json;
const evenements = Array.isArray(ev) ? ev.map((e) => e.x + ' : ' + e.y).join(', ') : 'indisponible';
const g = $('Google : note et avis').first().json || {};
const sc = $('Search Console : requêtes').first().json || {};
const clics = (sc.rows || []).reduce((s, r) => s + r.clicks, 0), impressions = (sc.rows || []).reduce((s, r) => s + r.impressions, 0);
