const lignes = [
  'Andy Construct · tableau de bord de ' + p.mois, '',
  'EN BREF',
  '- Demandes : ' + mois.length + ' (A ' + parPrio('A') + ', B ' + parPrio('B') + ', C ' + parPrio('C') + ', hors cible ' + parPrio('hors-cible') + ')',
  '- Offres envoyées : ' + offres,
  '- Chantiers signés : ' + gagnees.length + ' (CHF ' + montant.toLocaleString('fr-CH') + ')',
  '- Avis Google : ' + (g.userRatingCount !== undefined ? g.userRatingCount + ' (note ' + g.rating + ')' : 'indisponible'),
  '- Délai médian de premier contact : ' + mediane, '',
  'SOURCES DES DEMANDES', ...Object.entries(sources).sort((a, b) => b[1] - a[1]).map(([s, n]) => '- ' + s + ' : ' + n), '',
  'SITE (Umami, sans cookie)', '- Visites : ' + visites, '- Événements : ' + evenements, '',
  'RECHERCHE (Search Console)', '- Clics : ' + (sc.rows ? clics : 'indisponible') + ' · impressions : ' + (sc.rows ? impressions : 'indisponible'),
  ...(sc.rows || []).slice(0, 10).map((r) => '  · ' + r.keys[0] + ' : ' + r.clicks + ' clics, position ' + r.position.toFixed(1)), '',
  'Dépenses publicitaires (Google Ads, Meta, LinkedIn) : à compléter par l\'agence, avec 3 actions pour le mois suivant.',
];
const texte = lignes.join('\n') + '\n';
return [{ json: { courriel: { de: $env.AC_EMAIL_EXPEDITEUR, a: [$env.AC_EMAILS_ASSOCIES, $env.AC_AGENCE_EMAIL].filter(Boolean).join(','), repondre_a: $env.AC_AGENCE_EMAIL || $env.AC_EMAIL_EXPEDITEUR,
  sujet: 'Andy Construct · tableau de bord de ' + p.mois, texte, html: '<pre style="font:16px/1.5 Arial,sans-serif;white-space:pre-wrap">' + texte.replace(/</g, '&lt;') + '</pre>' } } }];
